//: ログイン試行ロックアウト (生成時 標準装備)
// パスワード総当たり (ブルートフォース) 対策。5回連続失敗で15分ロック。
// インメモリ実装のため単一インスタンス構成で有効。マルチインスタンス本番では
// LoginAttempt テーブル (Prisma) もしくは Redis へ差し替えること。
//
// authorize() への配線例:
//   if (isLockedOut(email)) return null;            // ロック中は照合せず拒否
//   const ok = await bcrypt.compare(password, user.passwordHash);
//   if (!ok) { recordLoginFailure(email); return null; }
//   clearLoginFailures(email);

const MAX_FAILURES = 5;
const LOCKOUT_MS = 15 * 60 * 1000; // 15分

type Entry = { failures: number; lockedUntil: number };

const attempts = new Map<string, Entry>();

function keyOf(identifier: string): string {
  return identifier.toLowerCase().trim();
}

export function isLockedOut(identifier: string): boolean {
  const e = attempts.get(keyOf(identifier));
  if (!e) return false;
  if (e.lockedUntil > Date.now()) return true;
  if (e.lockedUntil !== 0 && e.lockedUntil <= Date.now()) {
    attempts.delete(keyOf(identifier)); // ロック期間満了 → リセット
  }
  return false;
}

export function recordLoginFailure(identifier: string): void {
  const k = keyOf(identifier);
  const e = attempts.get(k) ?? { failures: 0, lockedUntil: 0 };
  e.failures += 1;
  if (e.failures >= MAX_FAILURES) {
    e.lockedUntil = Date.now() + LOCKOUT_MS;
  }
  attempts.set(k, e);
}

export function clearLoginFailures(identifier: string): void {
  attempts.delete(keyOf(identifier));
}
